/// Map model alias to full model ID
///
/// # Arguments
/// * `model` - Model alias or full ID
///
/// # Returns
/// Full model ID
pub fn map_model_to_id(model: &str) -> String {
    if let Some(base) = strip_one_million_suffix(model) {
        return format!("{}[1m]", map_base_model_to_id(base));
    }
    map_base_model_to_id(model)
}

/// Rolling Claude Code aliases. Claude Code resolves them itself, so a direct
/// run keeps them and follows the vendor's newest model (hive-mind#2290).
pub const ROLLING_CLAUDE_ALIASES: [&str; 3] = ["opus", "sonnet", "haiku"];

fn strip_one_million_suffix(model: &str) -> Option<&str> {
    let split = model.len().checked_sub(4)?;
    (model.is_char_boundary(split) && model[split..].eq_ignore_ascii_case("[1m]") && split > 0)
        .then(|| &model[..split])
}

fn map_base_model_to_id(model: &str) -> String {
    lookup_model_alias(&get_model_map(), model)
        .or_else(|| expand_claude_version_shorthand(model))
        .unwrap_or_else(|| model.to_string())
}

/// Expand a version shorthand for a known Claude family (hive-mind#2591).
///
/// `opus-6` / `opus-6.1` / `claude-opus-6.1` become `claude-opus-6` /
/// `claude-opus-6-1`, so a release newer than this build reaches Claude Code
/// under its canonical ID.
pub fn expand_claude_version_shorthand(model: &str) -> Option<String> {
    let lower = model.to_ascii_lowercase();
    let rest = lower.strip_prefix("claude-").unwrap_or(&lower);
    let (family, version) = rest.split_once('-')?;
    let (major, minor) = match version.split_once(['.', '-']) {
        Some((major, minor)) => (major, Some(minor)),
        None => (version, None),
    };
    let is_number = |part: &str| !part.is_empty() && part.bytes().all(|b| b.is_ascii_digit());
    if family.is_empty()
        || !family.bytes().all(|b| b.is_ascii_lowercase())
        || !is_number(major)
        || !minor.is_none_or(is_number)
    {
        return None;
    }
    let known_family = get_model_map().values().any(|id| {
        id.strip_prefix("claude-")
            .and_then(|id| id.strip_prefix(family))
            .and_then(|id| id.strip_prefix('-'))
            .is_some_and(|id| id.starts_with(|c: char| c.is_ascii_digit()))
    });
    known_family.then(|| match minor {
        Some(minor) => format!("claude-{family}-{major}-{minor}"),
        None => format!("claude-{family}-{major}"),
    })
}

/// Model value for `--model` / `--fallback-model`: rolling aliases stay
/// (lower-cased, `[1m]` kept), everything else maps to its full ID.
pub fn model_arg(model: &str) -> String {
    let (base, suffix) = strip_one_million_suffix(model).map_or((model, ""), |base| (base, "[1m]"));
    let lower = base.to_ascii_lowercase();
    if ROLLING_CLAUDE_ALIASES.contains(&lower.as_str()) {
        format!("{lower}{suffix}")
    } else {
        map_model_to_id(model)
    }
}

/// Claude command build options
#[derive(Debug, Clone, Default)]
pub struct ClaudeBuildOptions {
    pub prompt: Option<String>,
    pub prompt_file: Option<String>,
    pub system_prompt: Option<String>,
    pub append_system_prompt: Option<String>,
    pub model: Option<String>,
    pub fallback_model: Option<String>,
    pub print: bool,
    pub verbose: bool,
    pub json: bool,
    pub json_input: bool,
    pub replay_user_messages: bool,
    pub resume: Option<String>,
    pub session_id: Option<String>,
    pub fork_session: bool,
    pub read_only: bool,
    /// Approve each command (`--permission-mode default` + stream-json relay)
    pub approve_each: bool,
    pub executable: Option<String>,
    pub extra_env: Vec<(String, String)>,
    /// Variables removed from the inherited environment (`env -u`)
    pub unset_env: Vec<String>,
    pub extra_args: Vec<String>,
    pub skip_default_safety_flags: bool,
    pub permission_mode: Option<String>,
    /// Caller owns the child's stdin and streams the prompt + permission
    /// responses as NDJSON frames, so no `--prompt` arg is passed.
    pub stream_input: bool,
}

impl ClaudeBuildOptions {
    /// Create new options
    pub fn new() -> Self {
        Self::default()
    }
}

/// Build command line arguments for Claude
///
/// # Arguments
/// * `options` - Build options
///
/// # Returns
/// Vector of CLI arguments
pub fn build_args(options: &ClaudeBuildOptions) -> Vec<String> {
    let mut args = Vec::new();

    if options.approve_each {
        // Per-command approval: ask before each tool use via the stream-json
        // can_use_tool control protocol. `default` keeps Claude's own prompting
        // active instead of bypassing it; the relay answers each request.
        args.push("--permission-mode".to_string());
        args.push("default".to_string());
    } else if options.read_only {
        args.push("--permission-mode".to_string());
        args.push("plan".to_string());
    } else if let Some(ref permission_mode) = options.permission_mode {
        args.push("--permission-mode".to_string());
        args.push(permission_mode.clone());
    } else if !options.skip_default_safety_flags {
        // Permission bypass is enabled by default for autonomous execution.
        args.push("--dangerously-skip-permissions".to_string());
    }

    if let Some(ref model) = options.model {
        args.push("--model".to_string());
        args.push(model_arg(model));
    }

    if let Some(ref fallback_model) = options.fallback_model {
        let mapped_fallback = model_arg(fallback_model);
        args.push("--fallback-model".to_string());
        args.push(mapped_fallback);
    }

    // In stream-input mode the prompt is written to stdin as NDJSON frames by
    // the per-command approval relay, so it is not passed as a --prompt arg.
    if options.prompt_file.is_none() && !options.stream_input {
        if let Some(ref prompt) = options.prompt {
            args.push("-p".to_string());
            args.push(prompt.clone());
        }
    }

    if let Some(ref system_prompt) = options.system_prompt {
        args.push("--system-prompt".to_string());
        args.push(system_prompt.clone());
    }

    if let Some(ref append_system_prompt) = options.append_system_prompt {
        args.push("--append-system-prompt".to_string());
        args.push(append_system_prompt.clone());
    }

    if options.verbose || options.json {
        args.push("--verbose".to_string());
    }

    if options.prompt.is_none()
        && (options.print || options.json || options.json_input || options.prompt_file.is_some())
    {
        args.push("-p".to_string()); // Print mode
    }

    // JSON output mode - use stream-json format per issue #3
    if options.json {
        args.push("--output-format".to_string());
        args.push("stream-json".to_string());
    }

    // JSON input mode - use stream-json format per issue #3
    if options.json_input {
        args.push("--input-format".to_string());
        args.push("stream-json".to_string());
    }

    // Replay user messages (only with stream-json input/output)
    if options.replay_user_messages {
        args.push("--replay-user-messages".to_string());
    }

    // Session management
    if let Some(ref session_id) = options.session_id {
        args.push("--session-id".to_string());
        args.push(session_id.clone());
    }

    if let Some(ref resume) = options.resume {
        args.push("--resume".to_string());
        args.push(resume.clone());
    }

    if options.fork_session {
        args.push("--fork-session".to_string());
    }

    args.extend(options.extra_args.clone());

    args
}

/// Build complete command string for Claude
///
/// # Arguments
/// * `options` - Build options
///
/// # Returns
/// Complete command string
pub fn build_command(options: &ClaudeBuildOptions) -> String {
    let args = build_args(options);
    let args_str: Vec<String> = args.iter().map(|a| escape_arg(a)).collect();
    let executable = options.executable.as_deref().unwrap_or("claude");
    let command = format!(
        "{} {}",
        build_command_head(executable, &options.unset_env, &options.extra_env, &[]),
        args_str.join(" ")
    )
    .trim()
    .to_string();

    // In stream-input mode the caller owns the child's stdin and writes the
    // prompt and permission responses as NDJSON frames (per-command approval
    // relay), so no prompt is piped here.
    if options.stream_input {
        command
    } else if let Some(prompt_file) = &options.prompt_file {
        format!("cat {} | {}", escape_arg(prompt_file), command)
    } else {
        command
    }
}

/// Parse JSON messages from Claude output
/// Claude outputs NDJSON (newline-delimited JSON) in JSON mode
///
/// # Arguments
/// * `output` - Raw output string
///
/// # Returns
/// Vector of parsed JSON messages
pub fn parse_output(output: &str) -> Vec<Value> {
    parse_json_records(output)
}

/// Extract session ID from Claude output
///
/// # Arguments
/// * `output` - Raw output string
///
/// # Returns
/// Session ID or None
pub fn extract_session_id(output: &str) -> Option<String> {
    let messages = parse_output(output);

    for msg in messages {
        if let Some(session_id) = msg.get("session_id").and_then(|v| v.as_str()) {
            return Some(session_id.to_string());
        }
    }

    None
}

/// Usage statistics
#[derive(Debug, Clone, Default, serde::Serialize)]
#[serde(rename_all = "camelCase")]
pub struct ClaudeUsage {
    pub input_tokens: u64,
    pub output_tokens: u64,
    pub cache_creation_tokens: u64,
    pub cache_read_tokens: u64,
}

/// Extract usage statistics from Claude output
///
/// # Arguments
/// * `output` - Raw output string
///
/// # Returns
/// Usage statistics
pub fn extract_usage(output: &str) -> ClaudeUsage {
    let messages = parse_output(output);
    let mut result = ClaudeUsage::default();
    for record in usage::records("claude", &messages) {
        result.input_tokens += count(record, usage::INPUT);
        result.output_tokens += count(record, usage::OUTPUT);
        result.cache_read_tokens += count(record, usage::CACHE_READ);
        result.cache_creation_tokens += count(record, usage::CACHE_WRITE);
    }
    result
}

/// Claude tool configuration
#[derive(Debug, Clone)]
pub struct ClaudeTool {
    pub name: &'static str,
    pub display_name: &'static str,
    pub executable: &'static str,
    pub supports_json_output: bool,
    pub supports_json_input: bool,
    pub supports_system_prompt: bool,
    pub supports_append_system_prompt: bool,
    pub supports_resume: bool,
    pub supports_fork_session: bool,
    pub supports_session_id: bool,
    pub supports_fallback_model: bool,
    pub supports_verbose: bool,
    pub supports_replay_user_messages: bool,
    pub supports_read_only: bool,
    pub supports_ask: bool,
    pub default_model: &'static str,
}

impl Default for ClaudeTool {
    fn default() -> Self {
        Self {
            name: "claude",
            display_name: "Claude Code CLI",
            executable: "claude",
            supports_json_output: true,
            supports_json_input: true, // Claude supports stream-json input format
            supports_system_prompt: true,
            supports_append_system_prompt: true, // Supports --append-system-prompt
            supports_resume: true,
            supports_fork_session: true,   // Supports --fork-session
            supports_session_id: true,     // Supports --session-id
            supports_fallback_model: true, // Supports --fallback-model
            supports_verbose: true,        // Supports --verbose
            supports_replay_user_messages: true, // Supports --replay-user-messages
            supports_read_only: true,      // Supports --permission-mode plan
            supports_ask: true, // Supports --permission-mode default with stream-json relay
            default_model: "opus",
        }
    }
}

